function supplier(c,favorite=false){const r=rec(c.id);return `<article class="supplier selectable"><div class="supplier-check"><input type="checkbox" data-compare="${c.id}" aria-label="选择 ${esc(c.name)} 对比" ${state.selected.includes(c.id)?'checked':''}></div><div class="supplier-body"><div class="supplier-title"><div><div class="row">${link(esc(c.name),'detail',`data-id="${c.id}" style="font-size:17px;font-weight:600;color:#202b3f"`)}</div><p class="small muted" style="margin-top:6px">${c.country} · ${c.type}</p></div>${heart(c.id)}</div><div style="margin-top:11px">${c.sources.map(tag).join('')}</div><div class="supplier-meta"><div><p class="small muted">匹配产品</p><p class="supplier-product">${esc(c.product)}</p><p class="small muted">HS ${esc(d().hs||'8544')} · ${/cable el|kabel/i.test(d().q)?'词典扩展匹配':'产品线索命中'}</p><p class="small muted" style="margin-top:7px">联系方式：${c.contact?'电话 / WhatsApp / 官网':'暂无联系方式数据'}</p></div><div><p class="small muted">近期贸易记录</p><p style="margin-top:6px">${c.records===null?'暂无可统计记录':c.records+' 条'}</p><p class="small muted">${c.period}${c.records!==null&&!c.coverageComplete?' · 部分覆盖':''}</p><p class="small muted" style="margin-top:7px">企业规模：${c.employees}</p>${c.quantity!==null?'<p class="small muted">供货量（贸易记录）：'+c.quantity.toLocaleString()+' '+c.unit+'</p>':''}</div></div><div class="supplier-foot">${favorite?`<div class="small muted">${esc(label(d()))}<br>收藏于 ${r.first} · 我的评价 ${r.stars?r.stars+' 星':'未评价'} · 跟进 ${esc(r.follow)}</div>`:'<span></span>'}<div class="row">${link('查看详情','detail',`data-id="${c.id}"`)}</div></div></div></article>`}
function listTable(list,favorite=false){return table(['选择','企业名称 / 国家','匹配产品 / HS','来源类别','联系 / 规模','近期记录 / 统计期',...(favorite?['我的评价 / 跟进']:[]),'操作'],list.map(c=>[`<input type="checkbox" data-compare="${c.id}" aria-label="选择 ${esc(c.name)} 对比" ${state.selected.includes(c.id)?'checked':''}>`,`${link(esc(c.name),'detail',`data-id="${c.id}"`)}<p class="small muted">${c.country} · ${c.type}</p>`,esc(c.product)+'<p class="small muted">'+esc(d().hs||'8544')+'</p>',c.sources.map(tag).join(''),(c.contact?'有公开联系方式':'暂无联系方式数据')+'<p class="small muted">'+c.employees+'</p>',(c.records===null?'暂无可统计记录':c.records+' 条')+'<p class="small muted">'+c.period+'</p>',...(favorite?[(rec(c.id).stars?rec(c.id).stars+' 星':'未评价')+'<p class="small muted">'+esc(rec(c.id).follow)+'</p>']:[]),`<div class="row">${heart(c.id)}${link('查看详情','detail',`data-id="${c.id}"`)}</div>`]),'supplier-table')}
function discover(blank=false){const list=filtered().filter(c=>c.ch===state.channel);return `${searchForm(blank)}${blank?'<div class="empty" style="margin-top:28px"><h2>从产品与国家开始寻找供应商</h2><p>产品关键词与 HS Code 至少填写一项；同时填写取交集。</p></div>':`<div class="tabs">${[['A','本地 · 贸易线索'],['B','本地 · 名录'],['C','境外 · 贸易线索']].map(([id,name])=>`<button type="button" data-channel="${id}" class="${state.channel===id?'on':''}">${id} ${name} <span class="tag">${filtered().filter(c=>c.ch===id).length}</span></button>`).join('')}</div>${toolbar()}${comparebar()}<section id="supplier-results">${list.length?(state.mode==='cards'?'<div class="supplier-grid">'+list.map(c=>supplier(c)).join('')+'</div>':listTable(list)):`<div class="empty"><h2>${d().country==='MX'&&state.channel==='B'?'该通道暂无数据覆盖':'未找到匹配供应商'}</h2><p>${d().country==='MX'&&state.channel==='B'?'尚无可用本地名录，不能理解为该国家没有供应商。':'可调整企业名称或高级筛选，不会自动放宽产品与 HS 条件。'}</p>${button('清空结果筛选','clear-filters')}</div>`}</section><div class="pager"><span>共 ${list.length} 家</span><select aria-label="每页条数"><option>20 条/页</option><option>10 条/页</option></select><button disabled aria-label="上一页">‹</button><span class="tag">1</span><button disabled aria-label="下一页">›</button></div>`}`}
function advanced(){const f=state.filters;modal('高级筛选',`<form id="advanced-form" class="form"><div class="filter-group"><h3>来源类别</h3><div class="chips">${['海关','官方目录','登记镜像','黄页/公司目录','B2B 平台','企业/官网','公开网页'].map(s=>`<label class="check"><input type="checkbox" name="sources" value="${s}" ${f.sources.includes(s)?'checked':''}>${s}</label>`).join('')}</div></div><div class="filter-group"><h3>企业属性</h3><div class="chips">${['制造商','贸易商','分销商'].map(t=>`<label class="check"><input type="checkbox" name="types" value="${t}" ${f.types.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><div class="cols"><label class="field"><span>HS Code · 当前结果内细筛</span><input name="hs" value="${esc(f.hs)}" placeholder="输入 HS 前缀"></label><label class="field"><span>联系方式</span><select name="contact"><option value="">不限</option><option value="yes" ${f.contact==='yes'?'selected':''}>有公开联系方式</option><option value="no" ${f.contact==='no'?'selected':''}>暂无联系方式数据</option></select></label></div><label class="field"><span>企业规模</span><select name="size">${[['','不限'],['10-49','10–49 人'],['50-99','50–99 人'],['100-499','100–499 人'],['unknown','暂无规模数据']].map(([v,n])=>`<option value="${v}" ${f.size===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="cols"><label class="field"><span>供货量下限（可观察贸易数量）</span><input name="minQty" type="number" min="0" value="${esc(f.minQty)}" placeholder="不填则不限"></label><label class="field"><span>单位</span><select name="unit"><option value="kg" ${f.unit==='kg'?'selected':''}>千克 kg</option><option value="t" ${f.unit==='t'?'selected':''}>吨 t</option></select></label></div><p class="small muted">数量按原始单位及实际统计期筛选，缺失不视为 0，不代表产能或承诺交付量。不同单位不直接混比。</p><div class="row"><button type="submit" class="primary">应用筛选</button>${button('重置筛选','clear-filters')}</div></form>`)}
function favorites(){const groups=demands.filter(dm=>Object.entries(records).some(([k,r])=>k.startsWith(dm.id+'|')&&r.fav));return `<label class="field" style="max-width:430px"><span>按搜索条件分组 · 仅本人可见</span><select id="demand-select">${groups.map(dm=>`<option value="${dm.id}" ${dm.id===state.demand?'selected':''}>${esc(label(dm))}</option>`).join('')}</select></label>${toolbar(true)}${comparebar()}${filtered(true).length?(state.mode==='cards'?'<div class="supplier-grid">'+filtered(true).map(c=>supplier(c,true)).join('')+'</div>':listTable(filtered(true),true)):'<div class="empty"><h2>还没有收藏的供应商</h2><p>点亮红色爱心保存候选，原搜索条件下重新收藏可恢复个人记录。</p>'+button('去寻找供应商','discover','',true)+'</div>'}`}
function coverage(c){return `<div class="panel coverage"><h2>来源与覆盖期</h2>${table(['来源类别','可用内容 / 覆盖范围','数据状态'],c.sources.map(source=>[source,source==='海关'?'当前产品 / 国家 · '+c.period:'企业资料 / 产品线索；不适用贸易统计',source==='海关'?(c.records===null?'暂无可统计记录':'示例区间有覆盖'):'示例资料可用']))}<p class="small muted" style="margin-top:10px">同一企业多来源只计一家。数量、趋势和明细均使用实际覆盖期；无覆盖不视为 0。</p></div>`}
function info(items){return `<div class="infogrid">${items.map(([label,value])=>`<div><p class="small muted">${label}</p><p>${value||'暂无信息'}</p></div>`).join('')}</div>`}
function lineChart(title,values,labels,unit='',color='#2457ff'){const W=600,H=220,left=50,top=20,bottom=178,right=580,max=Math.max(1,...values),x=i=>left+i*(right-left)/Math.max(1,values.length-1),y=v=>bottom-v/max*(bottom-top),pts=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg class="linechart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}"><title>${esc(title)}：${values.map((v,i)=>labels[i]+' '+v+unit).join('；')}</title>${[0,.5,1].map(k=>`<line x1="${left}" y1="${y(max*k)}" x2="${right}" y2="${y(max*k)}" stroke="#e8edf6"/><text x="${left-10}" y="${y(max*k)+4}" text-anchor="end" class="charttext">${Math.round(max*k).toLocaleString()}</text>`).join('')}<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="${color}" stroke-width="2"><title>${esc(labels[i])}：${v.toLocaleString()} ${unit}</title></circle><text x="${x(i)}" y="205" text-anchor="middle" class="charttext">${esc(labels[i])}</text>`).join('')}</svg>`}
function basicInfo(c){const known=c.id==='c1'||c.id==='c3';return `<section class="panel"><h2>企业概况</h2>${info([['企业简介',known?'电缆与导体供应商资料样例，经营信息来自演示目录；需进一步核实。':'暂无信息'],['行业 / 经营类别',known?'电气设备 / 线缆（目录分类）':'暂无信息'],['成立年份',known?'2009 年（演示）':'暂无信息'],['员工规模',c.employees]])}</section><section class="panel"><h2>主体识别</h2>${info([['税号 / 登记号',known?(c.country==='中国'?'中国登记号：暂无信息':'墨西哥 · 税号 RFC：DEMO-RFC（演示，未核验）'):'暂无信息'],...(c.country==='中国'?[['统一社会信用代码','暂无信息'],['经营状态','暂无信息']]:[['登记状态','暂无信息']])])}<p class="small muted section-note">观察到号码不等于官方核验；号码类型按国家分别标识。</p></section><section class="panel"><h2>联系方式</h2>${info([['企业官网',c.contact?link('访问企业官网 ↗','website'):'未核实官网'],['公开电话',c.contact?'演示电话 '+link('复制','copy'):'暂无信息'],['WhatsApp',c.contact?'演示 WhatsApp '+link('复制','copy'):'暂无信息'],['公开邮箱','暂无信息'],['联系人',c.contact?'演示联系人（身份未核验）':'暂无信息']])}<p class="small muted section-note">仅展示获授权的公开联系字段；有号码不表示已接通，平台商铺不标为官网。</p></section><section class="data-notes"><span>资料采集：2024-07-01（演示）</span><span>企业资料更新时间：暂无信息</span></section>`}
function catalog(c){if(!c.sources.some(x=>['企业/官网','B2B 平台','官方目录'].includes(x)))return [];const src=c.country==='印度尼西亚'?'id':'es';return [
{id:c.id+'-connector',kind:'connector',names:{zh:'工业连接器',en:'Industrial connector',es:'Conector industrial',id:'Konektor industri'},aliases:['连接器','connector','conector','konektor'],hs:'8536',category:'电气设备 / 连接器',brand:'DEMO',model:'CONN-02',spec:'16 A · 250 V（目录演示）',price:'3.00–5.00',currency:'USD',unit:'件',moq:'100 件',lang:src},
{id:c.id+'-cable',kind:'cable',names:{zh:'电力电缆',en:'Power cable',es:'Cable eléctrico',id:'Kabel listrik'},aliases:['电缆','线缆','cable','kabel'],hs:'8544',category:'电气设备 / 线缆',brand:'DEMO',model:'CABLE-01',spec:'600/1000 V · 4 mm²（目录演示）',price:'12.50–16.00',currency:'USD',unit:'米',moq:'500 米',lang:src},
{id:c.id+'-copper',kind:'copper',names:{zh:'铜导线',en:'Copper wire',es:'Alambre de cobre',id:'Kawat tembaga'},aliases:['铜线','铜导线','copper','cobre','tembaga'],hs:'7408',category:'金属材料 / 铜导线',brand:'DEMO',model:'COPPER-03',spec:'99.9% Cu · 2 mm（目录演示）',price:'8.00–10.00',currency:'USD',unit:'kg',moq:'200 kg',lang:src}
].map(p=>({...p,company:c.id,description:p.names[p.lang]+' · '+p.spec,updated:'2024-06-28',collected:'2024-07-01',origin:null}))}
function catalogMatch(p){const q=d().q.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase(),word=!q||p.aliases.some(x=>q.includes(x.toLowerCase())||x.toLowerCase().includes(q));return word&&(!d().hs||p.hs.startsWith(d().hs))}
function catalogOrdered(c){return catalog(c).sort((a,b)=>Number(catalogMatch(b))-Number(catalogMatch(a))||a.id.localeCompare(b.id))}
function productName(p){return p.names[effectiveLocale()==='zh-CN'?'zh':effectiveLocale()]||p.names.en}
function productsInfo(c){const all=catalogOrdered(c),p=all.find(p=>p.id===state.selectedProduct)||all[0];return `<section class="panel"><div class="row between"><h2>目录产品 / 服务</h2><span class="small muted">${all.length} 个产品 · 当前搜索匹配优先</span></div>${all.length?`<div class="catalog-list">${all.map(x=>`<button type="button" class="catalog-tile ${x.id===p.id?'on':''}" data-action="select-product" data-id="${x.id}"><div class="row between"><strong data-source-text data-product-name="${x.id}">${productName(x)}</strong>${catalogMatch(x)?'<span class="tag blue">当前搜索匹配</span>':''}</div><p class="small muted" data-source-text>${x.names[x.lang]}</p><p class="small muted">${x.brand} / ${x.model} · HS ${x.hs}</p></button>`).join('')}</div><article class="catalog-product catalog-detail"><div class="product-placeholder" role="img" aria-label="暂无目录图片"><span>▧</span><small>暂无目录图片</small></div><div class="catalog-content"><div class="row"><h3 data-source-text data-product-name="${p.id}">${productName(p)}</h3>${tag('目录产品 · 演示')}</div><p class="small muted section-note"><span>产品原文</span>：<span data-source-text>${p.names[p.lang]}</span></p>${info([['产品类目',p.category],['品牌 / 型号',p.brand+' / '+p.model],['技术规格',p.spec],['产品描述',p.description],['目录商品关联 HS',p.hs+' · 核定的演示目录映射']])}<div class="match-proof">${catalogMatch(p)?'当前搜索匹配：产品词及关联 HS 符合本次条件':'该商品属于此供应商完整目录，未命中当前搜索'}</div></div></article>`:'<div class="empty compact"><h3>暂无可展示的目录产品</h3><p>可在下方查看贸易记录中的商品，不补造目录规格或图片。</p></div>'}</section><section class="panel"><h2>商品交易条件</h2>${p?`<p class="small muted"><span>对应选中产品</span>：<span data-source-text data-product-name="${p.id}">${productName(p)}</span></p>${info([['目录报价 / 币种 / 计价单位',p.price+' '+p.currency+' / '+p.unit+'（目录演示）'],['MOQ / 最低起订量',p.moq+'（仅该商品）'],['库存状态','目录标注可供货；非实时现货承诺'],['商品原产地','暂无信息']])}<p class="small muted section-note">产品更新时间 ${p.updated} · 采集时间 ${p.collected} · 报价不代表最终成交价。</p>`:'<p class="muted">暂无信息</p>'}</section><section class="panel"><h2>贸易记录中的商品</h2>${c.records===null?'<p class="muted">暂无可统计记录</p>':table(['商品原文','关联 HS','方向 / 当前国家','操作'],[[esc(c.product),esc(d().hs||'8544'),'供方 / '+country(d().country),link('查看贸易画像','trade-tab')]])}<p class="small muted section-note">展示该供应商全部获授权目录产品；目录与贸易商品分别关联，不默认为同一 SKU。</p></section>`}
function tradeInfo(c){if(c.records===null)return `<section class="scope-box"><h3>统计范围</h3><p>${esc(label(d()))} · 当前授权国家</p></section>${coverage(c)}<div class="empty"><h2>暂无可统计记录</h2><p>无覆盖不置零，不生成贸易额、趋势或伙伴指标。</p></div>`;const full=c.id==='c1',counts=full?[1,2,0,3,2,4]:[c.records],months=full?['01 月','02 月','03 月','04 月','05 月','06 月']:['覆盖期'];return `<section class="scope-box"><div><h3>统计范围</h3><p>${esc(label(d()))} · 供方相关记录 · 目的国 ${country(d().country)}</p><p class="small muted">覆盖区间 ${c.period} · 海关 · 日期类型：登记日（演示口径）</p></div>${tag('仅当前授权国家')}</section>${coverage(c)}<section class="panel"><h2>核心指标与贸易规模</h2><div class="trade-stats">${[['近期记录数',c.records+' 条'],['最近记录日期','2024-06-21 · 登记日'],['可识别贸易伙伴',full?'3 家':'暂无信息'],['贸易额 / 货值性质',full?'100,000 USD · CIF':'暂无信息'],['商品数量及单位',c.quantity===null?'暂无信息':c.quantity.toLocaleString()+' '+c.unit],['重量',full?'132,000 kg · 毛重':'暂无信息'],['TEU','暂无信息']].map(([label,value])=>`<div class="stat"><p class="small muted">${label}</p><strong>${value}</strong></div>`).join('')}</div><p class="small muted section-note">记录数不等于订单数；数量、重量与 TEU 分开，币种/FOB-CIF/粒度不可混加，缺失不计零。</p></section><section class="panel"><h2>贸易趋势</h2><div class="chart-grid"><div class="analytics-card"><h3>${full?'月度记录数':'覆盖期记录数'} · 条</h3>${lineChart('记录数趋势',counts,months,'条')}</div><div class="analytics-card"><h3>月度贸易额 · USD / CIF</h3>${full?lineChart('月度贸易额趋势',[10000,15000,0,20000,18000,37000],months,'USD','#28a493'):'<div class="empty compact"><p>金额口径或覆盖不足，暂不展示曲线。</p></div>'}</div></div><p class="small muted section-note">同范围、同源、同口径展示；无覆盖月份留缺口，已确认覆盖内无记录才为 0。</p></section><section class="panel"><h2>贸易伙伴</h2>${full?table(['贸易伙伴（演示）','角色','关联记录','最近记录日期'],[['伙伴 A','收货方','7 条','2024-06-21 · 登记日'],['伙伴 B','收货方','3 条','2024-06-12 · 登记日'],['伙伴 C','收货方','2 条','2024-05-08 · 登记日']]):'<p class="muted">缺少有效身份依据，暂无可识别伙伴统计。</p>'}</section><section class="panel"><h2>记录明细</h2>${table(['日期 / 类型','方向 / 发收货方','商品 / HS / 目的国','货值 / 口径','数量 / 重量 / TEU'],[['2024-06-21 / 登记日','供方：'+esc(c.name)+'<br>收货方：伙伴 A',esc(c.product)+'<br>HS '+esc(d().hs||'8544')+' · '+country(d().country),full?'12,000 USD / CIF':'暂无信息',full?'10,000 kg / 11,000 kg 毛重 / 暂无 TEU':'暂无信息'],['2024-06-12 / 登记日','供方：'+esc(c.name)+'<br>收货方：伙伴 B','Electric cable / '+esc(d().hs||'8544')+'<br>'+country(d().country),full?'8,000 USD / CIF':'暂无信息',full?'7,000 kg / 7,700 kg 毛重 / 暂无 TEU':'暂无信息']])}<p class="small muted section-note">展示 2 条演示明细摘要；完整记录日期倒序分页。单条金额不由汇总值回填。</p></section><section class="data-notes"><span>文件发布日期：2024-07-01（演示）</span><span>成功接入时间：2024-07-02（演示）</span><span>上述时间均不替代贸易事件日期</span></section>`}
function detail(){const c=co(),r=rec(c.id);let body=state.tab==='基础信息'?basicInfo(c):state.tab==='产品与服务'?productsInfo(c):state.tab==='贸易画像'?tradeInfo(c):`<div class="panel"><h2>我的评价</h2><p style="font-size:23px;color:#bd8422;margin:16px 0">${r&&(!r.first||r.fav)&&r.stars?'★'.repeat(r.stars)+'☆'.repeat(5-r.stars):'尚未评价'}</p><p class="original">${r&&(!r.first||r.fav)?esc(r.comment):'重新收藏后可恢复保留的评价。'}</p><p class="small muted" style="margin:16px 0">本人在本搜索条件下的判断，仅本人可见。</p>${button('写评价','review',`data-id="${c.id}"`,true)}</div>`;return `${link('← 返回列表','back')}<div class="detail-head"><div><h2>${esc(c.name)}</h2><p class="muted" style="margin:6px 0">${c.country} · ${c.type}</p><p>${c.sources.map(tag).join('')}</p></div><div class="row">${heart(c.id)}${button('加入对比','add-compare',`data-id="${c.id}"`)}${button(r?.fav?'跟进：'+r.follow:'跟进','follow',`data-id="${c.id}" ${r?.fav?'':'disabled title="请先收藏该供应商"'}`)}</div></div><div class="tabs">${['基础信息','产品与服务','贸易画像','我的评价'].map(t=>`<button type="button" data-tab="${t}" class="${state.tab===t?'on':''}">${t}</button>`).join('')}</div>${body}`}
function comparisonGroups(){const prod=c=>catalogOrdered(c).find(catalogMatch),val=(c,k)=>c.id==='c1'?({founded:'2009',tax:'RFC：DEMO-RFC（未核验）',industry:'电气设备 / 线缆',partners:'3 家',amount:'100,000 USD · CIF',weight:'132,000 kg · 毛重',last:'2024-06-21 · 登记日'}[k]||'暂无信息'):'暂无信息';const groups=[
['基础信息',[
['企业国家 / 属性',c=>c.country+' / '+c.type],['来源组合',c=>c.sources.join(' + ')],['企业简介',c=>c.id==='c1'?'线缆与导体供应商目录样例；企业自述待核实。':'暂无信息'],['行业 / 经营类别',c=>val(c,'industry')],['成立年份',c=>val(c,'founded')],['员工规模',c=>c.employees],['税号 / 登记号',c=>val(c,'tax')],['经营状态',c=>'暂无信息'],['企业官网',c=>c.contactFields.includes('website')?'有公开官网（演示）':'暂无信息'],['电话 / WhatsApp',c=>c.contactFields.filter(x=>['phone','whatsapp'].includes(x)).map(x=>x==='phone'?'公开电话':'WhatsApp').join(' / ')||'暂无信息'],['邮箱 / 联系人',c=>c.contactFields.includes('email')?'公开邮箱 / 联系人待核验':'暂无信息']]],
['产品与服务',[
['本次匹配产品',c=>prod(c)?productName(prod(c)):'无可靠目录匹配'],['目录产品 / 服务',c=>catalogOrdered(c).map(p=>productName(p)).join('；')||'暂无目录产品'],['产品类目',c=>prod(c)?.category||'暂无信息'],['品牌 / 型号',c=>prod(c)?prod(c).brand+' / '+prod(c).model:'暂无信息'],['规格 / 描述',c=>prod(c)?.spec||'暂无信息'],['目录报价 / 计价单位',c=>prod(c)?prod(c).price+' '+prod(c).currency+' / '+prod(c).unit:'暂无信息'],['MOQ',c=>prod(c)?.moq||'暂无信息'],['库存 / 商品原产地',c=>prod(c)?'目录可供（非实时） / 暂无原产地':'暂无信息'],['产品 / HS 匹配依据',c=>prod(c)?'审核词组及可靠目录 HS '+prod(c).hs:'仅贸易线索，目录关联待核实'],['贸易商品原文 / HS',c=>c.records===null?'暂无可统计记录':c.product+' / '+(d().hs||'未填 HS')],['资料更新时间',c=>prod(c)?.updated||'暂无信息']]],
['贸易画像',[
['统计范围 / 日期类型',c=>label(d())+' / 供方相关记录 / 登记日（演示）'],['近期贸易记录数',c=>c.records===null?'暂无可统计记录':c.records+' 条'],['实际覆盖期',c=>c.period],['覆盖可比性',c=>c.records===null?'无贸易覆盖':c.coverageComplete?'完整统一窗口':'部分覆盖，不与完整窗口直接比高低'],['最近记录日期',c=>val(c,'last')],['可识别贸易伙伴',c=>val(c,'partners')],['贸易额 / 货值口径',c=>val(c,'amount')],['商品数量 / 单位',c=>c.quantity===null?'暂无信息':c.quantity.toLocaleString()+' '+c.unit],['重量',c=>val(c,'weight')],['TEU',c=>'暂无信息'],['趋势 / 记录明细',c=>c.records===null?'暂无可统计记录':'查看详情中的同范围趋势与明细']]],
['我的判断',[
['我的评价',c=>rec(c.id)?.stars?rec(c.id).stars+' 星 · '+rec(c.id).comment:'未评价'],['个人跟进',c=>rec(c.id)?.fav?rec(c.id).follow:'未收藏']]]
];return groups;}
function comparisonCurrent(){const list=state.selected.map(id=>C.find(c=>c.id===id));if(list.length<2)return '<div class="empty"><h2>选择 2～5 家供应商开始对比</h2><p>仅比较相同产品、HS 与国家条件下的候选。</p>'+button('去选择企业','discover','',true)+'</div>';const groups=comparisonGroups();let total=0;const body=groups.map(([name,rows])=>{const shown=state.diffOnly?rows.filter(([,f])=>new Set(list.map(f)).size>1):rows;if(!shown.length)return '';total+=shown.length;return `<tbody><tr class="comparison-group"><th colspan="${list.length+1}" scope="rowgroup">${name}</th></tr>${shown.map(([n,f])=>`<tr><th scope="row">${n}</th>${list.map(c=>`<td ${name==='我的判断'?'data-source-text':''}>${esc(f(c))}</td>`).join('')}</tr>`).join('')}</tbody>`}).join('');return `<div class="comparison-basket"><div class="row">${list.map(c=>`<span class="basket-chip">${esc(c.name)}<button type="button" data-action="remove-compare" data-id="${c.id}" aria-label="移除 ${esc(c.name)}">×</button></span>`).join('')}${list.length<5?button('＋ 再加一家','discover'):''}</div>${link('清空对比篮','clear-compare')}</div><div class="toolbar"><p class="small muted">检索条件：${esc(label(d()))}</p><div class="row"><label class="check"><input type="checkbox" id="diff-only" ${state.diffOnly?'checked':''}>只看差异</label>${button('导出 PDF','export','',true)}</div></div><div class="hint">同一基础条件下比较；不同覆盖期、币种、单位与货值性质只并列呈现，不直接排名。</div><div class="tablebox comparison-scroll"><table class="comparetable"><thead><tr><th>对比项</th>${list.map(c=>`<th><strong>${esc(c.name)}</strong><p class="small muted">${esc(c.country)} · ${esc(c.type)}</p>${link('查看详情','detail',`data-id="${c.id}"`)}</th>`).join('')}</tr></thead>${body||`<tbody><tr><td colspan="${list.length+1}" class="empty compact">所选企业在当前可见字段中没有差异。</td></tr></tbody>`}</table></div><p class="small muted section-note">共展示 ${total} 项可见字段；缺失不代表零、否或已核验，私评仅本人可见。</p>`}
function compareTabs(){return `<div class="tabs" aria-label="对比与导出页签">${['当前对比','历史导出'].map(t=>`<button type="button" data-compare-tab="${t}" class="${state.compareTab===t?'on':''}">${t}</button>`).join('')}</div>`}
function ensureReports(){if(state.reports.length)return;state.reports.push({id:'R-DEMO-001',label:'电缆 · 8544 · 墨西哥',country:'MX',createdAt:'2026-11-06 09:00',status:'已完成',items:['c1','c3'].map(id=>({...getRecordBody(id),comment:records['D1|'+id]?.comment||''}))})}
function exportHistory(){ensureReports();return `<div class="toolbar"><p class="small muted">仅本人导出 · 报告内容按生成时的资料快照固定</p><span class="tag">${state.reports.length} 份报告</span></div>${table(['报告编号 / 生成时间','检索条件','企业数','状态','操作'],[...state.reports].reverse().map(r=>[r.id+'<p class="small muted">'+r.createdAt+'</p>',esc(r.label),r.items.length,tag(r.status),`<div class="row">${link('查看报告','preview-report',`data-id="${r.id}"`)}${link('下载 PDF','download-report',`data-id="${r.id}"`)}</div>`]))}<p class="small muted section-note">历史导出不会重新拼接当前对比。查看与下载仍需当前有效权限；原型仅演示报告预览和下载入口。</p>`}
function comparison(){return compareTabs()+(state.compareTab==='历史导出'?exportHistory():comparisonCurrent())}
function users(){return `<div class="toolbar"><span class="small muted">以用户为单位维护账号与授权；公司名称仅为选填资料</span></div>${table(['用户名 / 手机号','公司名称（选填）','账号状态','开通方式','操作'],accounts.map(a=>[esc(a.username)+'<p class="small muted">'+esc(a.phone)+'</p>',esc(a.company||'未填写'),statusTag(a.status)+(a.enabled===false?tag('已停用'):''),a.origin==='P0'?'直接开通':'审批注册',`<div class="row">${link('配置授权','user-permissions',`data-id="${a.id}"`)}${link(a.enabled===false?'启用':'停用','toggle-user',`data-id="${a.id}"`)}</div>`]))}<div class="hint">用户权限来自所勾选角色与额外权限。账号停用后无法登录，已登录会话及下载权限同步失效。</div>`}
function permissions(){const a=accounts.find(a=>a.id===state.permissionUser)||accounts[0];let body='';if(state.permissionTab==='角色管理'){const r=roles.find(r=>r.id===state.roleEditor)||roles[0];body=`<div class="toolbar"><span class="small muted">角色绑定一套权限；修改后作用于所有关联用户</span>${button('新增角色','new-role','',true)}</div>${table(['角色名称','角色 key','关联用户','操作'],roles.map(x=>[esc(x.name),esc(x.id),accounts.filter(a=>(a.roleIds||[]).includes(x.id)).length,link('配置权限','edit-role',`data-id="${x.id}"`)]))}<div class="panel"><h2>配置角色：${esc(r.name)}</h2><form id="role-form" class="form" data-id="${r.id}" style="max-width:none"><label class="field" style="max-width:380px"><span>角色名称 *</span><input name="roleName" value="${esc(r.name)}" required></label>${table(['页面 / 操作','路由 / key','角色包含权限'],P.map(([name,route,key])=>[name,`<code>${route}</code>`,`<label class="check"><input type="checkbox" name="permission" value="${key}" aria-label="角色权限 ${name}" ${r.permissions.includes(key)?'checked':''}>授予</label>`]))}<div><button type="submit" class="primary">保存角色权限</button></div></form></div>`}else{const inherited=roleUnion(a.roleIds||[]),allowed=effective(a);body=`<form id="permission-form" class="form" style="max-width:none"><label class="field" style="max-width:450px"><span>选择用户</span><select id="permission-user" name="userId">${accounts.map(x=>`<option value="${x.id}" ${a.id===x.id?'selected':''}>${esc(x.username)} · ${esc(x.phone)}</option>`).join('')}</select></label><div class="filter-group"><h3>勾选角色 · 支持多个</h3><div class="chips">${roles.map(r=>`<label class="check"><input type="checkbox" name="roleIds" value="${r.id}" ${a.roleIds?.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div></div>${table(['页面 / 操作','路由 / key','角色授予','额外权限'],P.map(([name,route,key])=>[name,`<code>${route}</code>`,`<span data-inherited="${key}">${inherited.includes(key)?'允许':'—'}</span>`,`<label class="check"><input type="checkbox" name="extra" value="${key}" aria-label="额外权限 ${name}" ${a.extraPermissions?.includes(key)?'checked':''}>允许</label>`]))}<div><button type="submit" class="primary">保存用户授权</button></div></form>`}return `<div class="tabs" aria-label="权限管理页签">${['用户授权','角色管理'].map(t=>`<button type="button" data-permission-tab="${t}" class="${state.permissionTab===t?'on':''}">${t}</button>`).join('')}</div><div class="hint">用户有效权限 = 所选角色权限的并集 ∪ 用户额外权限。国家按寻源目的国授权；未授予的页面、操作与国家默认无权。</div>${body}`}
function permissionPreview(){const f=$('#permission-form');if(!f)return;const inherited=roleUnion(new FormData(f).getAll('roleIds'));document.querySelectorAll('[data-inherited]').forEach(n=>n.textContent=inherited.includes(n.dataset.inherited)?'允许':'—')}
function newRole(){modal('新增角色',`<form id="new-role-form" class="form"><label class="field"><span>角色名称 *</span><input name="name" required maxlength="40"></label><label class="field"><span>角色 key *</span><input name="key" pattern="[a-zA-Z][a-zA-Z0-9_-]{1,31}" required placeholder="例如 sourcing_reviewer"></label><p id="role-error" class="error" role="alert"></p><button type="submit" class="primary">创建并配置权限</button></form>`)}
function statusTag(s){return `<span class="tag ${s==='approved'?'green':s==='pending'?'amber':''}">${{approved:'已通过',pending:'待审批',rejected:'已驳回'}[s]}</span>`}
function approvals(){return `<div class="toolbar"><p class="small muted">P2 注册审核 · 仅审批通过的账号可登录</p><select id="approval-filter" aria-label="审批状态"><option value="">全部状态</option><option value="pending">待审批</option><option value="approved">已通过</option><option value="rejected">已驳回</option></select></div>${table(['申请编号 / 用户名 / 手机号','公司名称（选填）','申请状态','注册方式','操作'],accounts.map(a=>[a.id+'<p class="small muted">'+esc(a.username)+' · '+esc(a.phone)+'</p>',esc(a.company||'未填写'),`<span data-reg-status="${a.status}">${statusTag(a.status)}</span>`,a.origin==='P0'?'P0 已开通存量':'P2 审批注册',a.status==='pending'?link('审核申请','approve-dialog',`data-id="${a.id}"`):link('查看结果','approve-dialog',`data-id="${a.id}"`)]))}<div class="hint">启用审批前已开通的账号沿用有效状态；新注册账号进入待审批。审批结果、授权范围和操作记录同时保存。</div>`}
function approveDialog(id){const a=accounts.find(x=>x.id===id);modal('注册申请审核',`<div class="approval-detail"><p>申请编号：${a.id}</p><p>用户名：${esc(a.username)}</p><p>手机号：${esc(a.phone)}</p><p>公司名称（选填）：${esc(a.company||'未填写')}</p><p>状态：${statusTag(a.status)}</p></div>${a.status==='pending'?`<form id="approval-form" class="form" data-id="${a.id}" style="margin-top:20px"><label class="field"><span>审核结果</span><select name="decision"><option value="approved">通过并开通</option><option value="rejected">驳回申请</option></select></label><div class="filter-group"><h3>角色授权 · 可多选</h3>${roles.map(r=>`<label class="check"><input type="checkbox" name="roleIds" value="${r.id}" ${r.id==='buyer'?'checked':''}>${esc(r.name)}</label>`).join('')}</div><label class="field"><span>审核说明 · 驳回必填</span><textarea name="reason" placeholder="说明审核结论或驳回原因"></textarea></label><p class="small muted">额外权限可在通过后进入“用户与权限”配置。</p><p id="approval-error" class="error" role="alert"></p><button type="submit" class="primary">确认审核</button></form>`:`<div class="panel"><p>${esc(a.reason||'注册开通状态已生效。')}</p><p class="small muted">实际系统保存审核人、时间及前后状态。</p></div>`}`)}
function evidence(){return `<div class="toolbar"><p class="small muted">补充或纠正结构化事实后，触发内部结果重算</p>${button('补充核验证据','verify','data-id="c2"',true)}</div>${table(['企业','相关产品 / 国家','证据状态','更新状态','操作'],C.slice(0,4).map(c=>[esc(c.name),'电缆 / 墨西哥',state.evidence.some(e=>e.company===c.id&&e.active)?'人工核验证据有效':'待抽检',state.evidence.some(e=>e.company===c.id)?'重算完成':'未更新',link('核验依据','verify',`data-id="${c.id}"`)]))}<div class="panel"><h2>核验历史</h2>${state.evidence.length?state.evidence.map(e=>`<div class="timeline"><div><strong>${esc(e.type)} · ${esc(e.value)}</strong><p class="small muted">${country(e.country)} · ${esc(e.product||'仅 HS')} / ${esc(e.hs||'未填 HS')} · ${esc(C.find(c=>c.id===e.company)?.name)}</p><p>${esc(e.reason)}</p><p class="small muted">证据版本 E${e.version} · ${e.active?'有效':'已撤销'}</p>${e.active?link('撤销证据并重算','withdraw-evidence',`data-index="${e.version-1}"`):''}</div></div>`).join(''):'<p class="muted">暂无核验记录。</p>'}</div>`}
function verify(id){const c=C.find(c=>c.id===id);modal('结构化证据核验',`<form id="evidence-form" class="form" data-id="${id}"><label class="field"><span>国家 *</span><select name="country" required><option value="MX" ${d().country==='MX'?'selected':''}>墨西哥</option><option value="ID" ${d().country==='ID'?'selected':''}>印度尼西亚</option></select></label><div class="cols"><label class="field"><span>产品关键词 · 与 HS 至少一项</span><input name="product" value="${esc(d().q)}" placeholder="输入产品"></label><label class="field"><span>HS Code</span><input name="hs" value="${esc(d().hs)}" placeholder="输入 HS 编码"></label></div><label class="field"><span>企业名称 *</span><input name="companyName" required list="evidence-companies" value="${esc(c.name)}" autocomplete="off"><datalist id="evidence-companies">${C.map(x=>`<option value="${esc(x.name)}">${x.country}</option>`).join('')}</datalist></label><label class="field"><span>证据类型 *</span><select name="type"><option>联系信息</option><option>主体信息</option><option>产品供货线索</option></select></label><label class="field"><span>字段值或事实 *</span><input name="value" required></label><label class="field"><span>依据 / 内部关联 *</span><input name="reference" required></label><label class="field"><span>核验说明 * · 10～500 字</span><textarea name="reason" required minlength="10" maxlength="500"></textarea></label><p id="evidence-error" class="error" role="alert"></p><p class="small muted">证据绑定所选国家、产品/HS 与企业；选定真实企业主体后保存并重算。</p><button type="submit" class="primary">保存证据并重算</button></form>`)}
function security(){return `${table(['策略 / 事件','作用对象','处置','状态','操作'],[['注册短信发送过频','手机号 / IP','限速或验证','观察中',link('查看策略','policy')],['连续企业 ID 遍历','账号 / IP','临时限制','待复核',link('恢复访问','unblock')],['短时大量详情请求','用户账号','分级验证','观察中',link('查看策略','policy')]])}<div class="hint">短信、登录与业务接口分别限流。正常用户应可完成注册及寻源；验证或管理员恢复后可继续操作。</div>`}
function ranking(){return `<div class="hint">综合排序按下列维度从上到下逐级比较；可拖动调整优先级，也可用上移/下移。贸易量优先固定先比较同口径记录数。</div><div class="rule-layout"><section><div class="row between"><h2>综合排序 · 维度优先级</h2><span class="tag">${JSON.stringify(state.sortDraft)===JSON.stringify(state.sortActive)?'与已发布一致':'草稿未发布'}</span></div><ol id="sort-rule-list" class="sort-rule-list">${state.sortDraft.map((id,i)=>{const r=SORT_RULES.find(x=>x.id===id);return `<li draggable="true" data-rule-item="${id}" tabindex="0"><span class="drag-handle" title="拖动调整顺序" aria-label="拖动 ${r.name}">⠿</span><span class="rule-index">${i+1}</span><div><strong>${r.name}</strong><p class="small muted">${r.desc}</p></div><div class="rule-actions">${button('↑','rule-up',`data-id="${id}" aria-label="上移 ${r.name}" ${i===0?'disabled':''}`)}${button('↓','rule-down',`data-id="${id}" aria-label="下移 ${r.name}" ${i===state.sortDraft.length-1?'disabled':''}`)}</div></li>`}).join('')}</ol><div class="row">${button('保存草稿','save-rule-draft')}${button('发布排序规则','publish-rules','',true)}${button('恢复初始顺序','reset-rules')}</div><p id="rule-error" class="error" role="alert"></p></section><aside class="rule-side"><h3>当前已发布版本 S${state.sortVersion}</h3><p class="small muted section-note">草稿调整不影响寻源结果；发布成功后，新请求统一使用同一版本。</p><h3 style="margin-top:24px">初始来源层级</h3><p class="small muted section-note">海关与名录证据齐全 → 海关 → 官方名录 → 商业名录 → 仅网页证据。再按资料完整度等维度细排。</p><h3 style="margin-top:24px">版本历史</h3>${state.sortVersions.map(v=>`<div class="rule-version"><span>S${v.version} · ${v.at}</span>${v.version===state.sortVersion?tag('当前版本'):link('回滚至此顺序','rollback-rules',`data-id="${v.version}"`)}</div>`).join('')}</aside></div><section class="panel"><h2>草稿效果预览 · 演示企业</h2>${table(['顺序','企业','来源','近期记录 / 覆盖期'],sortSuppliers(C.filter(c=>baseMatch(c)), 'recommended',state.sortDraft).slice(0,5).map((c,i)=>[i+1,c.name,c.sources.join(' + '),(c.records===null?'暂无可统计记录':c.records+' 条')+'<p class="small muted">'+c.period+'</p>']))}<p class="small muted section-note">只预览顺序，不展示内部企业评分；数据范围与许可条件先于排序生效。</p></section>`}
function moveRule(id,target){const next=state.sortDraft.filter(x=>x!==id);next.splice(Math.max(0,Math.min(target,next.length)),0,id);state.sortDraft=next;render()}
function validRules(order){return order.length===SORT_RULES.length&&new Set(order).size===SORT_RULES.length&&order.every(id=>SORT_RULES.some(r=>r.id===id))}
function publishRules(order,message='排序规则已发布'){if(!validRules(order)){note('规则维度必须完整且不重复');return}state.sortVersion++;state.sortActive=[...order];state.sortDraft=[...order];state.sortVersions.push({version:state.sortVersion,order:[...order],at:'2026-11-06 11:30'});render();note(message+'，后续综合排序请求使用版本 S'+state.sortVersion)}
function searchRows(){const words=['电缆','cable eléctrico','','kabel listrik'],days=['2026-10-31','2026-11-01','2026-11-02','2026-11-03','2026-11-04','2026-11-05','2026-11-06'],seed=days.flatMap((day,i)=>Array.from({length:[2,4,3,6,5,8,4][i]},(_,j)=>({product:words[(i+j)%4],hs:(i+j)%4===2?'7408':'8544',country:(i+j)%4===3?'ID':'MX',type:'supplier_search',id:`EV-DEMO-${i}-${j}`,time:day+' 09:30',result:(i+j)%5===0?'成功零结果':'成功有结果'})));return [...seed,...state.events.filter(e=>e.type==='supplier_search')].filter(r=>!state.analyticsCountry||r.country===state.analyticsCountry)}
function analytics(){const list=searchRows(),days=['10-31','11-01','11-02','11-03','11-04','11-05','11-06'],trend=days.map(day=>list.filter(r=>r.time.slice(5,10)===day).length);let body='';if(state.analyticsTab==='概览')body=`<div class="three"><div class="stat"><p class="small muted">搜索次数</p><strong>${list.length}</strong></div><div class="stat"><p class="small muted">搜索国家</p><strong>${new Set(list.map(v=>v.country)).size}</strong></div><div class="stat"><p class="small muted">反馈提交 · 全站</p><strong>${state.feedbacks.length}</strong></div></div><div class="chart-grid analytics-overview"><section class="analytics-card"><div class="row between"><h3>搜索次数趋势</h3><span class="small muted">按天 · 次</span></div>${lineChart('每日搜索次数',trend,days,'次')}<details class="small"><summary>查看趋势明细</summary>${table(['日期','搜索次数'],days.map((day,i)=>['2026-'+day,trend[i]]))}</details></section><section class="analytics-card"><h3>搜索国家分布</h3>${pieChart(list,'country')}</section></div><div class="panel"><h2>产品词输入分布</h2>${aggregate(list,'product',true)}</div>`;else if(state.analyticsTab==='产品词')body=aggregate(list,'product',true);else if(state.analyticsTab==='HS Code')body=aggregate(list,'hs');else if(state.analyticsTab==='国家')body=`<div class="analytics-card country-pie">${pieChart(list,'country')}</div>${aggregate(list,'country')}`;else body=table(['事件 ID / 时间','事件','产品输入','HS Code','国家','结果'],list.map(r=>[r.id+'<p class="small muted">'+r.time+'</p>',r.type,esc(r.product||'仅 HS 搜索'),esc(r.hs||'未填'),country(r.country),r.result||'成功有结果']));return `<div class="toolbar"><span class="small muted">2026-10-31 至 2026-11-06 · P2 演示采集窗口</span><select id="analytics-country" aria-label="统计国家"><option value="">全部已授权国家</option><option value="MX" ${state.analyticsCountry==='MX'?'selected':''}>墨西哥</option><option value="ID" ${state.analyticsCountry==='ID'?'selected':''}>印度尼西亚</option></select></div><div class="analysis-tabs">${['概览','产品词','HS Code','国家','埋点数据'].map(t=>`<button type="button" data-analysis="${t}" class="${state.analyticsTab===t?'on':''}">${t}</button>`).join('')}</div>${body}<p class="small muted section-note">图表与表格同一筛选范围；搜索次数与人数分开，悬停可查看数值。更新时间 2026-11-06 10:30；真实采集从 P2 启用起点开始。</p>`}
function pieChart(list,k){const map={};list.forEach(r=>map[r[k]]=(map[r[k]]||0)+1);const entries=Object.entries(map),total=list.length,colors=['#2457ff','#28a493','#a085ef','#f4b863'];let offset=0;return total?`<div class="pie-layout"><svg viewBox="0 0 200 200" role="img" aria-label="搜索国家占比，共 ${total} 次"><title>${entries.map(([key,n])=>country(key)+' '+n+' 次').join('；')}</title><circle cx="100" cy="100" r="66" fill="none" stroke="#eef2fa" stroke-width="24"/>${entries.map(([key,n],i)=>{const arc=n/total*414.69,out=`<circle cx="100" cy="100" r="66" fill="none" stroke="${colors[i%colors.length]}" stroke-width="24" stroke-dasharray="${arc} ${414.69-arc}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"><title>${country(key)}：${n} 次，${(n/total*100).toFixed(1)}%</title></circle>`;offset+=arc;return out}).join('')}<text x="100" y="98" text-anchor="middle" class="pie-total">${total}</text><text x="100" y="121" text-anchor="middle" class="charttext">次搜索</text></svg><div class="pie-legend">${entries.map(([key,n],i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${country(key)}</span><strong>${n} 次</strong><small>${(n/total*100).toFixed(1)}%</small></div>`).join('')}</div></div>`:'<div class="empty compact">当前范围暂无数据</div>'}
function aggregate(list,k,product=false){const map={};for(const r of list){const v=r[k]||(product?'仅 HS 搜索':'未填');map[v]=(map[v]||0)+1}return table([product?'用户输入的产品词':k==='hs'?'HS Code':'国家','搜索次数','占比'],Object.entries(map).sort((a,b)=>b[1]-a[1]).map(([v,n])=>[esc(k==='country'?country(v):v),n,(n/Math.max(1,list.length)*100).toFixed(2)+'%']))}
function feedbacks(){return `<div class="toolbar"><p class="small muted">按用户范围授权处理；联系字段独立授权</p><select id="feedback-filter" aria-label="反馈状态"><option>全部状态</option><option>待处理</option><option>处理中</option><option>已解决</option><option>已关闭</option></select></div>${table(['编号 / 主题','用户','分类','状态','操作'],state.feedbacks.map(f=>[esc(f.title)+'<p class="small muted">'+f.id+'</p>',esc(f.user),f.type,`<span data-feedback-state="${f.status}">${f.status}</span>`,link('查看并处理','feedback-detail',`data-id="${f.id}"`)]))}`}
function feedback(){feedbackRequest??='REQUEST-'+(++feedbackSequence);modal('反馈与支持',`<form id="feedback-form" class="form"><label class="field"><span>反馈类型 *</span><select name="type"><option>功能问题</option><option>数据问题</option><option>产品建议</option><option>其他</option></select></label><label class="field"><span>主题 * · 5～100 字</span><input name="title" minlength="5" maxlength="100" value="${esc(feedbackDraft.title||'')}" required></label><label class="field"><span>描述 * · 10～2000 字</span><textarea name="desc" minlength="10" maxlength="2000" required>${esc(feedbackDraft.desc||'')}</textarea></label><label class="field"><span>满意度（选填）</span><select name="satisfaction"><option value="">未选择</option>${[1,2,3,4,5].map(v=>'<option>'+v+'</option>').join('')}</select></label><div class="cols"><label class="field"><span>电话 · 电话/邮箱至少一项</span><input name="phone" type="tel" value="${esc(feedbackDraft.phone||'')}"></label><label class="field"><span>邮箱</span><input name="email" type="email" value="${esc(feedbackDraft.email||'')}"></label></div><p class="small muted">联系方式仅用于反馈处理，管理员通过所留信息联系。</p><p id="feedback-error" class="error" role="alert"></p><button type="submit" class="primary">提交反馈</button></form>`)}
function review(id){const r=rec(id);if(r?.first&&!r.fav){modal('恢复个人记录',`<p>重新收藏后可恢复原条件下的评价。</p>${button('重新收藏','restore-favorite',`data-id="${id}"`,true)}`);return}state.company=id;state.tab='我的评价';if(state.view!=='detail')go('detail');else render();modal('我的评价',`<p>${esc(C.find(c=>c.id===id).name)}</p><p class="small muted" style="margin:6px 0 20px">仅本人在本搜索条件下可见</p><form id="review-form" class="form" data-id="${id}"><label class="field"><span>我的星级 *</span><select name="stars" required><option value="">请选择星级</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${r?.stars===v?'selected':''}>${v} 星</option>`).join('')}</select></label><label class="field"><span>评价内容 · 最多 1000 字</span><textarea name="comment" maxlength="1000">${esc(r?.comment||'')}</textarea></label><div class="row"><button type="submit" class="primary">保存评价</button>${r?.stars?button('删除评价','delete-review',`data-id="${id}"`):''}</div></form>`)}
function follow(id){const r=rec(id);if(!r?.fav){note('请先收藏该企业');return}modal('个人候选跟进',`<p>${esc(C.find(c=>c.id===id).name)}</p><p class="small muted" style="margin:6px 0 20px">${esc(label(d()))}</p><form id="follow-form" class="form" data-id="${id}"><label class="field"><span>当前状态</span><select name="status">${['待联系','已联系','待进一步核验','已完成','不再考虑'].map(v=>`<option value="${v}" ${r.follow===v?'selected':''}>${v}</option>`).join('')}</select></label><button type="submit" class="primary">保存跟进</button></form><div class="panel"><h3>状态历史</h3>${r.history.map(v=>'<p class="small muted">'+esc(v)+'</p>').join('')||'<p class="small muted">首次状态：待联系</p>'}</div>`)}
function makeReport(){if(state.selected.length<2||state.selected.length>5){note('请选择 2～5 家供应商');return}ensureReports();const report={label:label(d()),country:d().country,id:'R-DEMO-'+String(state.reports.length+1).padStart(3,'0'),createdAt:'2026-11-06 10:30',status:'已完成',items:state.selected.map(id=>({...getRecordBody(id),comment:rec(id)?.comment||'',stars:rec(id)?.stars}))};state.reports.push(report);state.reportId=report.id;state.compareTab='历史导出';go('report')}
function report(){const r=state.reports.find(r=>r.id===state.reportId)||state.reports.at(-1);if(!r)return '<p>请先从对比页导出报告。</p>';return `<div class="toolbar"><p class="small muted">PDF 版式预览 · 不生成生产报告文件</p>${button('返回历史导出','export-history')}</div><article class="report"><h2>供应商对比报告</h2><p>检索条件：${esc(r.label)}</p><p class="small muted">${r.id} · ${r.createdAt} · 演示用户 buyer_demo</p>${r.items[0]?.details?r.items[0].details.map((g,gi)=>`<section class="panel"><h3>${g.group}</h3>${table(['对比项',...r.items.map(c=>esc(c.name))],g.rows.map((row,ri)=>[row.label,...r.items.map(c=>'<span data-source-text>'+esc(c.details[gi].rows[ri].value)+'</span>')]))}</section>`).join(''):table(['企业','产品','近期记录 / 区间','本人评语'],r.items.map(c=>[esc(c.name),esc(c.product),(c.records===null?'暂无可统计记录':c.records+' 条')+'<p class="small muted">'+c.period+'</p>',esc(c.comment)]))}<p class="small muted section-note">报告保留三个数据维度及本人判断的生成快照，不随后续资料或规则变更改写。</p></article>`}
const UI_LANGS=[['zh-CN','中文'],['en','English'],['es','Español'],['id','Bahasa Indonesia']];
const localLanguage=()=>d()?.country==='ID'?'id':'es';
function effectiveLocale(){return state.localePreference==='local'?localLanguage():state.lang}
const iconPaths={globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18M12 3c-5 5-5 13 0 18"/>',report:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>'};
function utilityIcon(type,action,title){return `<button type="button" class="utility-icon" data-action="${action}" title="${title}" aria-label="${title}" ${action==='language'?'aria-expanded="false" aria-haspopup="menu"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[type]}</svg></button>`}
function languageMenu(anchor=$('[data-action="language"]')){if($('#language-menu')){$('#language-menu').remove();document.querySelectorAll('[data-action="language"]').forEach(b=>b.setAttribute('aria-expanded','false'));return}const menu=document.createElement('div');menu.id='language-menu';menu.className='language-menu';menu.setAttribute('role','menu');menu.innerHTML=`<p class="small muted">语言 / Language</p><button type="button" role="menuitemradio" data-locale="local" aria-checked="${state.localePreference==='local'}">◎ <span>原国家语言</span> <small>${localLanguage()==='es'?'Español':'Bahasa Indonesia'}</small></button>${UI_LANGS.map(([id,label])=>`<button type="button" role="menuitemradio" data-locale="${id}" aria-checked="${state.localePreference===id}">${state.localePreference===id?'✓':'　'} <span data-source-text>${label}</span></button>`).join('')}`;(anchor?.closest('.drawer-head')||$('.header')).append(menu);anchor.setAttribute('aria-expanded','true');translate();resize()}
function setLocale(preference){state.localePreference=preference;state.lang=preference==='local'?localLanguage():preference;try{localStorage.setItem('sourcing-ui-locale',preference)}catch(e){}document.documentElement.lang=state.lang;$('#language-menu')?.remove();document.querySelectorAll('[data-action="language"]').forEach(b=>b.setAttribute('aria-expanded','false'));document.querySelectorAll('[data-product-name]').forEach(el=>{const p=C.flatMap(catalog).find(p=>p.id===el.dataset.productName);if(p)el.textContent=productName(p)});translate();resize()}
function render(){root.className='app'+(state.collapsed?' collapsed':'');const ns=state.platform==='admin'?navA:navB;root.innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">S</span><span class="brand-text">${state.platform==='admin'?'平台管理':'供应商寻源'}</span></div><nav class="nav" aria-label="一级导航">${ns.map(([id,icon,name])=>`<button type="button" class="navitem ${state.view===id?'on':''}" data-view="${id}" aria-label="${name}" title="${name}"><span class="navicon" aria-hidden="true">${icon}</span><span class="navlabel">${name}</span></button>`).join('')}</nav><div class="sidebar-footer"><button type="button" class="collapse-button" data-action="collapse" aria-label="${state.collapsed?'展开导航':'收起导航'}">${state.collapsed?'☰':'‹ 收起导航'}</button><button type="button" data-action="logout" class="link" aria-label="退出登录" title="${esc(user.username)} · 退出登录"><span class="avatar">S</span></button></div></aside><main class="main"><header class="header"><div><p class="breadcrumb">${state.platform==='admin'?'管理平台':'寻源平台'}</p><h1 id="title">${titles[state.view]||'供应商发现'}</h1></div><div class="row">${utilityIcon('globe','language','选择语言')}${state.platform==='sourcing'?utilityIcon('report','feedback','反馈与支持'):''}</div></header><div id="content"></div><div id="notice" class="notice" hidden role="status" aria-live="polite"></div><footer class="footer" id="footer">企业与统计为静态演示数据，尚未接入真实数据集</footer><div id="overlay"></div></main>`;const routes={discover:()=>discover(),home:()=>discover(true),favorites,detail,compare:comparison,users,permissions,approvals,evidence,security,ranking,analytics,feedbacks,report};$('#content').innerHTML=(routes[state.view]||routes.discover)();translate();resize()}
function doSearch(next){let dm=demands.find(x=>x.q.trim()===next.q.trim()&&x.hs===next.hs&&x.country===next.country);if(!dm){dm={id:'D'+(demands.length+1),...next};demands.push(dm)}state.demand=dm.id;if(state.localePreference==='local')state.lang=localLanguage();state.selectedProduct=null;state.selected=[];state.name='';state.filters={sources:[],types:[],hs:'',contact:'',minQty:'',unit:'kg',size:''};state.channel=['A','B','C'].find(ch=>C.some(c=>baseMatch(c,dm)&&c.ch===ch))||'A';log('supplier_search',{result:C.some(c=>baseMatch(c,dm))?'成功有结果':'成功零结果'});go('discover')}
function requestSearch(next){if(state.selected.length&&(next.q.trim()!==d().q.trim()||next.hs!==d().hs||next.country!==d().country)){pendingSearch=next;modal('搜索条件发生变化',`<p>产品、HS 或国家变化会清空已选的 ${state.selected.length} 家对比企业。</p><div class="row" style="margin-top:20px">${button('取消变更','cancel-search')}${button('确认清空并搜索','confirm-search','',true)}</div>`,true)}else doSearch(next)}
function favorite(id){const r=rec(id,true);r.fav=!r.fav;if(r.fav&&!r.first){r.first='2026-11-06 10:30';r.snapshot=getRecordBody(id)}if(!r.fav)state.selected=state.selected.filter(x=>x!==id);log('favorite_change',{action:r.fav?'save':'remove'});render();note(r.fav?'已收藏，原条件下的评价与跟进记录保留。':'已取消收藏，重新收藏可恢复个人记录。')}
